function JumpToLatest() {
  const { scrollToEnd, scrollToMessage } = useMessageScroller();
  const { currentAnchorId, atEnd } = useMessageScrollerVisibility();

  if (atEnd) return null;

  return (
    <Button size="sm" onPress={() => scrollToEnd()}>
      Jump to latest
    </Button>
  );
}
